using sv_fc3fb673a0f7483b92ee0b59c430d0ba.Models;

namespace sv_fc3fb673a0f7483b92ee0b59c430d0ba.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_fc3fb673a0f7483b92ee0b59c430d0ba.Models;

namespace sv_fc3fb673a0f7483b92ee0b59c430d0ba.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic pizza with tomato sauce, mozzarella, and fresh basil.", 30),
            new(2, "Spaghetti Carbonara", "Creamy pasta with egg, pancetta, and Parmesan cheese.", 25),
            new(3, "Tiramisu", "Layered coffee-flavored dessert with mascarpone cream.", 45),
            new(4, "Risotto alla Milanese", "Saffron-infused Arborio rice cooked slowly in broth.", 40),
        },
        [2] = new List<Recipe>
        {
            new(5, "Kung Pao Chicken", "Spicy stir-fried chicken with peanuts, vegetables, and chili peppers.", 35),
            new(6, "Mapo Tofu", "Silken tofu in a spicy, aromatic sauce with ground pork.", 20),
            new(7, "Spring Rolls", "Crispy rolls filled with vegetables and served with dipping sauce.", 50),
            new(8, "Hot and Sour Soup", "Tangy and spicy soup with tofu, mushrooms, and bamboo shoots.", 30),
        },
        [3] = new List<Recipe>
        {
            new(9, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion.", 60),
            new(10, "Guacamole", "Fresh avocado dip with lime, cilantro, and jalapeño.", 10),
            new(11, "Chicken Enchiladas", "Corn tortillas filled with chicken and topped with chili sauce.", 45),
            new(12, "Churros", "Fried dough pastry coated in cinnamon sugar.", 35),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

