        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
        {
            return new List<Recipe>();
        }

        return _currentSort == "popular"
            ? _recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : _recipes.OrderByDescending(r => r.Id).ToList();
    }

    private void OnSortChanged(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "newest";
        _currentSort = value;
        Navigation.NavigateTo(
            Navigation.GetUriWithQueryParameter("sort", value),
            replace: true);
    }

    private async Task Retry()
    {
        _errorMessage = null;
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Dispose();
    }
}

