    {
        var value = e.Value?.ToString() ?? "newest";
        _currentSort = value;
        Navigation.NavigateTo(
            Navigation.GetUriWithQueryParameter("sort", value),
            replace: true);
    }

    private async Task Retry()
    {
        _errorMessage = null;
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Dispose();
    }
}

